// The machine readable discriminator. One of `invalid` for a malformed or rejected request,
// `execution_failed` for a valid query that failed on the data it met (division by zero, a violated
// cardinality assertion), `not_found`, `conflict` for a lost optimistic race (an immediate retry may
// win — constraint violations are `invalid`, since retrying them cannot help), or `internal`.
type ProblemCode string

const (
	ProblemCodeInvalid         ProblemCode = "invalid"
	ProblemCodeExecutionFailed ProblemCode = "execution_failed"
	ProblemCodeNotFound        ProblemCode = "not_found"
	ProblemCodeConflict        ProblemCode = "conflict"
	ProblemCodeInternal        ProblemCode = "internal"
)

// AllValues returns all ProblemCode values.
func (ProblemCode) AllValues() []ProblemCode {
	return []ProblemCode{
		ProblemCodeInvalid,
		ProblemCodeExecutionFailed,
		ProblemCodeNotFound,
		ProblemCodeConflict,
		ProblemCodeInternal,
	}
}

// MarshalText implements encoding.TextMarshaler.
func (s ProblemCode) MarshalText() ([]byte, error) {
	switch s {
	case ProblemCodeInvalid:
		return []byte(s), nil
	case ProblemCodeExecutionFailed:
		return []byte(s), nil
	case ProblemCodeNotFound:
		return []byte(s), nil
	case ProblemCodeConflict:
		return []byte(s), nil
	case ProblemCodeInternal:
		return []byte(s), nil
	default:
		return nil, errors.Errorf("invalid value: %q", s)
	}
}

// UnmarshalText implements encoding.TextUnmarshaler.
func (s *ProblemCode) UnmarshalText(data []byte) error {
	switch ProblemCode(data) {
	case ProblemCodeInvalid:
		*s = ProblemCodeInvalid
		return nil
	case ProblemCodeExecutionFailed:
		*s = ProblemCodeExecutionFailed
		return nil
	case ProblemCodeNotFound:
		*s = ProblemCodeNotFound
		return nil
	case ProblemCodeConflict:
		*s = ProblemCodeConflict
		return nil
	case ProblemCodeInternal:
		*s = ProblemCodeInternal
		return nil
	default:
		return errors.Errorf("invalid value: %q", data)
	}
}

